from collections import defaultdict

rows = [  # 가상 자재 기준정보
    {"자재": "M-1", "유형": "가스", "유해물질": "Y", "공급사": "A"},
    {"자재": "M-2", "유형": "가스", "유해물질": None, "공급사": "A"},
    {"자재": "M-3", "유형": "부품", "유해물질": "N", "공급사": None},
    {"자재": "M-4", "유형": "부품", "유해물질": None, "공급사": "B"},
    {"자재": "M-5", "유형": "부품", "유해물질": None, "공급사": "B"},
    {"자재": "M-6", "유형": "케미컬", "유해물질": "Y", "공급사": "C"},
]
COLS = ["유해물질", "공급사"]
cnt, empty = defaultdict(int), defaultdict(lambda: defaultdict(int))
for r in rows:
    cnt[r["유형"]] += 1
    for c in COLS:
        empty[r["유형"]][c] += r[c] is None
for t in cnt:
    print(t, {c: f"{empty[t][c] / cnt[t]:.0%}" for c in COLS})
total = sum(r[c] is None for r in rows for c in COLS)
print("전체 빈칸 비율:", f"{total / (len(rows) * len(COLS)):.1%}")

# 가스 {'유해물질': '50%', '공급사': '0%'}
# 부품 {'유해물질': '67%', '공급사': '33%'}
# 케미컬 {'유해물질': '0%', '공급사': '0%'}
# 전체 빈칸 비율: 33.3%
